style.css:
@-moz-document domain("youtube.com") {
/* Fondo principal */
  html, body,
  ytd-app,
  ytd-browse,
  ytd-watch-flexy {
    background: #101827 !important;
  }

  /* Barra superior */
  #masthead,
  ytd-masthead {
    background: #111D34 !important;
    border-bottom: 2px solid #D4AF37 !important;
  }

  /* Menú lateral */
  ytd-guide-renderer,
  ytd-mini-guide-renderer {
    background: #152541 !important;
  }

  /* Textos */
  #video-title,
  #title,
  yt-formatted-string,
  #channel-name {
    color: #F5F5F5 !important;
  }

  /* Títulos de videos */
  #video-title {
    font-weight: 700 !important;
  }

  /* Color dorado en enlaces y selección */
  a:hover,
  ytd-guide-entry-renderer:hover {
    color: #FFD700 !important;
  }

  /* Barra de búsqueda */
  #search-form,
  #search-input,
  ytd-searchbox {
    background: #1C2E4C !important;
    border-color: #D4AF37 !important;
    border-radius: 20px !important;
  }

  /* Botones */
  button,
  yt-button-shape button {
    border-radius: 18px !important;
  }

  /* Barra de progreso del video */
  .ytp-play-progress {
    background: #FFD700 !important;
  }

  /* Punto de progreso */
  .ytp-scrubber-button {
    background: #FFFFFF !important;
    border: 2px solid #FFD700 !important;
  }

  /* Etiqueta Mbappé */
  ytd-masthead #logo::after {
    content: "  ⚽ KM9";
    color: #FFD700;
    font-size: 17px;
    font-weight: 900;
    margin-left: 14px;
    letter-spacing: 2px;
  }

  /* Miniaturas */
  ytd-thumbnail img {
    border-radius: 14px !important;
  }

  ytd-rich-grid-media:hover img,
  ytd-video-renderer:hover img {
    box-shadow: 0 0 18px #D4AF3770 !important;
  }

  /* Scroll */
  ::-webkit-scrollbar {
    width: 9px;
  }

  ::-webkit-scrollbar-thumb {
    background: #D4AF37;
    border-radius: 10px;
  }

  /* Selección de texto */
  ::selection {
    background: #FFD700;
    color: #101827;
  }
}
